ts><nts n="HIAT:ip" id="Seg_2179"><![CDATA[ ]]></nts></ts></ts><ts n="sc" id="Seg_2180" s="T86" e="T87"><ts n="HIAT:u" id="Seg_2182" s="T86" e="T87"><ts n="HIAT:w" id="Seg_2184" s="T86" e="T86.TIE6.1">Ус</ts><nts n="HIAT:ip" id="Seg_2185"><![CDATA[ ]]></nts><ats n="HIAT:non-pho" id="Seg_2186" s="T86.TIE6.1" e="T86.TIE6.2">•</ats><nts n="HIAT:ip" id="Seg_2187"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2189" s="T86.TIE6.2" e="T87">Успокойтесь</ts><nts n="HIAT:ip" id="Seg_2190">!</nts><nts n="HIAT:ip" id="Seg_2191"><![CDATA[ ]]></nts></ts></ts><ts n="sc" id="Seg_2192" s="T98" e="T101"><ts n="HIAT:u" id="Seg_2194" s="T98" e="T101"><ts n="HIAT:w" id="Seg_2196" s="T98" e="T98.TIE6.1">Давайте</ts><nts n="HIAT:ip" id="Seg_2197">,</nts><nts n="HIAT:ip" id="Seg_2198"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2200" s="T98.TIE6.1" e="T98.TIE6.2">давайте</ts><nts n="HIAT:ip" id="Seg_2201">,</nts><nts n="HIAT:ip" id="Seg_2202"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2204" s="T98.TIE6.2" e="T98.TIE6.3">не</ts><nts n="HIAT:ip" id="Seg_2205"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2207" s="T98.TIE6.3" e="T99">будем</ts><nts n="HIAT:ip" id="Seg_2208"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2210" s="T99" e="T99.TIE6.1">делать</ts><nts n="HIAT:ip" id="Seg_2211"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2213" s="T99.TIE6.1" e="T99.TIE6.2">этого</ts><nts n="HIAT:ip" id="Seg_2214"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2216" s="T99.TIE6.2" e="T99.TIE6.3">в</ts><nts n="HIAT:ip" id="Seg_2217"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2219" s="T99.TIE6.3" e="T99.TIE6.4">этой</ts><nts n="HIAT:ip" id="Seg_2220"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2222" s="T99.TIE6.4" e="T100">студии</ts><nts n="HIAT:ip" id="Seg_2223">,</nts><nts n="HIAT:ip" id="Seg_2224"><![CDATA[ ]]></nts><nts n="HIAT:ip" id="Seg_2225"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2227" s="T100" e="T101">пожалуйста</ts><nts n="HIAT:ip" id="Seg_2228">.</nts><nts n="HIAT:ip" id="Seg_2229"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE6"><ts n="sc" id="Seg_2230" s="T23" e="T24"><ts n="e" id="Seg_2232" s="T23" e="T24">Мы - это "Миракс"? </ts></ts><ts n="sc" id="Seg_2233" s="T41" e="T43"><ts n="e" id="Seg_2235" s="T41" e="T42">Это Башня Федерац </ts><ts n="e" id="Seg_2237" s="T42" e="T43">ий? </ts></ts><ts n="sc" id="Seg_2238" s="T63" e="T72"><ts n="e" id="Seg_2240" s="T63" e="T64">А • • Александр Евгеньевич, • пожалуйста. </ts><ts n="e" id="Seg_2242" s="T64" e="T65">Я понимаю, что это будет </ts><ts n="e" id="Seg_2244" s="T65" e="T66"> • я понимаю, что это • будет ааа • </ts><ts n="e" id="Seg_2246" s="T66" e="T67">кра • кра • сивая кар </ts><ts n="e" id="Seg_2248" s="T67" e="T68">тина. </ts><ts n="e" id="Seg_2250" s="T68" e="T69">• Но, • но я </ts><ts n="e" id="Seg_2252" s="T69" e="T70">вас умоляю, </ts><ts n="e" id="Seg_2254" s="T70" e="T71">столько, • столько людей </ts><ts n="e" id="Seg_2256" s="T71" e="T72">уже дрались в этой студии? </ts></ts><ts n="sc" id="Seg_2257" s="T77" e="T81"><ts n="e" id="Seg_2259" s="T77" e="T78">Давайте эту охра </ts><ts n="e" id="Seg_2261" s="T78" e="T79">ну сюдa. </ts><ts n="e" id="Seg_2263" s="T79" e="T80">Зовите уже</ts><ts n="e" id="Seg_2265" s="T80" e="T81">охрану! </ts></ts><ts n="sc" id="Seg_2266" s="T86" e="T87"><ts n="e" id="Seg_2268" s="T86" e="T87">Ус • Успокойтесь! </ts></ts><ts n="sc" id="Seg_2269" s="T98" e="T101"><ts n="e" id="Seg_2271" s="T98" e="T99">Давайте, давайте, не будем </ts><ts n="e" id="Seg_2273" s="T99" e="T100">делать этого в этой студии, </ts><ts n="e" id="Seg_2275" s="T100" e="T101"> пожалуйста. </ts></ts></segmentation><annotation name="en" tierref="TIE12"><ta id="Seg_2276" s="T23" e="T24">We're Mirax?  </ta><ta id="Seg_2277" s="T41" e="T43">Is that the Fed Tower?  </ta><ta id="Seg_2278" s="T63" e="T64">And Alexander Evgenievich, please.   </ta><ta id="Seg_2279" s="T64" e="T68">I realise that it will be a red card. I realise that it will be a red card.     </ta><ta id="Seg_2280" s="T68" e="T72">But, please, so many, so many people have already fought in this studio?  </ta><ta id="Seg_2281" s="T77" e="T79">Let's get that ochre over here.   </ta><ta id="Seg_2282" s="T79" e="T81">Call the guards!  </ta><ta id="Seg_2283" s="T86" e="T87">Ush! Calm down!  </ta><ta id="Seg_2284" s="T98" e="T101">Come on, come on, let's not do this in this studio, please.  </ta></annotation></segmented-tier><segmented-tier id="TIE7" speaker="SPK2" category="v" type="t" display-name="KG [v]"><timeline-fork start="T19" end="T20"><tli id="T19.TIE7.1"/>
